import java.time.LocalTime;import java.util.*;public class Task12{interface PricingRule{double fee(int m,LocalTime t);}static class Hourly implements PricingRule{final double rate;Hourly(double r){rate=r;}public double fee(int m,LocalTime t){return ((m+59)/60)*rate;}}static class Flat implements PricingRule{final double amount;Flat(double a){amount=a;}public double fee(int m,LocalTime t){return amount;}}static class Van implements PricingRule{public double fee(int m,LocalTime t){double r=(!t.isBefore(LocalTime.of(9,0))&&t.isBefore(LocalTime.of(17,0)))?60:30;return ((m+59)/60)*r;}}static class Vehicle{final String reg;final PricingRule rule;Vehicle(String r,PricingRule p){reg=r;rule=p;}}static class Facility{final String[][]slots;Facility(int...n){slots=new String[n.length][];for(int i=0;i<n.length;i++)slots[i]=new String[n[i]];}int[]allocate(String r){for(int f=0;f<slots.length;f++)for(int s=0;s<slots[f].length;s++)if(slots[f][s]==null){slots[f][s]=r;return new int[]{f,s};}return null;}}static double bill(Vehicle v,int m,LocalTime t,boolean pass){return pass?0:v.rule.fee(m,t);}public static void main(String[]x){Facility f=new Facility(2,3,1,4,2);Vehicle eb=new Vehicle("EB01",new Flat(25)),van=new Vehicle("VAN01",new Van());System.out.println("Floors: "+f.slots.length);System.out.println("E-bike slot: "+Arrays.toString(f.allocate(eb.reg)));System.out.println("E-bike flat: Rs "+bill(eb,130,LocalTime.of(10,0),false));System.out.println("Van peak: Rs "+bill(van,120,LocalTime.of(10,0),false));System.out.println("Van off-peak: Rs "+bill(van,120,LocalTime.of(18,0),false));System.out.println("Visitor day pass: Rs "+bill(van,120,LocalTime.of(10,0),true));}}